using UnityEngine; using UnityEditor; [InitializeOnLoad] public class ExtractPositionsAuto { static ExtractPositionsAuto() { EditorApplication.delayCall += () => { string output = ""; string[] names = {"Bedroom_Shell", "Wardrobe", "Bed", "Fan", "StudyDesk", "Fridge", "Door"}; foreach(string n in names) { GameObject obj = GameObject.Find(n); if (obj != null) { Vector3 p = obj.transform.position; Vector3 r = obj.transform.rotation.eulerAngles; Vector3 s = obj.transform.localScale; output += $"{n}|{p.x}f, {p.y}f, {p.z}f|{r.x}f, {r.y}f, {r.z}f|{s.x}f, {s.y}f, {s.z}f\n"; } } System.IO.File.WriteAllText("extracted_positions.txt", output); }; } }
